'use strict';

const fs = require('node:fs');
const dgram = require('node:dgram');
const net = require('node:net');
const { spawnSync } = require('node:child_process');

if (process.getuid() !== 65532) {
  throw new Error(`fixture expected uid 65532, received ${process.getuid()}`);
}

for (const name of [
  'HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'NO_PROXY',
  'http_proxy', 'https_proxy', 'all_proxy', 'no_proxy',
]) {
  if ((process.env[name] ?? '') !== '') {
    throw new Error(`fixture received inherited proxy configuration in ${name}`);
  }
}

const status = fs.readFileSync('/proc/self/status', 'utf8');
const effectiveCapabilities = /^CapEff:\s*([0-9a-f]+)$/im.exec(status)?.[1];
if (!effectiveCapabilities || !/^0+$/.test(effectiveCapabilities)) {
  throw new Error(`fixture expected zero effective capabilities, received ${effectiveCapabilities || 'unknown'}`);
}

function expectDenied(operation, description) {
  try {
    operation();
  } catch (error) {
    if (error && (error.code === 'EACCES' || error.code === 'EPERM')) {
      return;
    }
    throw error;
  }
  throw new Error(`fixture unexpectedly ${description}`);
}

expectDenied(() => fs.readdirSync('/trace'), 'read the trace directory');
expectDenied(() => fs.writeFileSync('/trace/forged', 'forged'), 'wrote to the trace directory');

function attempt(operation) {
  try {
    operation();
  } catch (_) {
    // Expected inside the read only, offline test container.
  }
}

attempt(() => fs.readFileSync(`${process.env.HOME}/.ssh/id_rsa`, 'utf8'));
attempt(() => fs.writeFileSync('/etc/behaviorlock-should-not-exist', 'blocked'));
attempt(() => fs.writeFileSync('/work/behaviorlock-fixture-output', 'observed'));
attempt(() => {
  const descriptor = fs.openSync('/work/behaviorlock-descriptor-target', 'w+');
  fs.ftruncateSync(descriptor, 0);
  fs.closeSync(descriptor);
  fs.readdirSync('/work');
});
attempt(() => spawnSync('/bin/sh', ['-c', '/bin/sh -c true'], { timeout: 1000 }));
attempt(() => spawnSync('/bin/sleep', ['0.01'], { timeout: 1000 }));
attempt(() => spawnSync('/usr/bin/strace', [
  '-qq', '-o', '/work/behaviorlock-nested-strace', '-p', String(process.pid),
], { timeout: 1000 }));

function attemptTCP() {
  return new Promise((resolve) => {
    const socket = net.connect({ host: '198.51.100.1', port: 443 });
    const finish = () => {
      socket.destroy();
      resolve();
    };
    socket.once('connect', finish);
    socket.once('error', finish);
    socket.setTimeout(500, finish);
  });
}

function attemptDNSDatagram() {
  return new Promise((resolve) => {
    const socket = dgram.createSocket('udp4');
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      try { socket.close(); } catch (_) { /* already closed */ }
      resolve();
    };
    socket.once('error', finish);
    socket.send(Buffer.from([0, 1, 1, 0]), 53, '198.51.100.53', finish);
    setTimeout(finish, 500).unref();
  });
}

function exerciseLoopbackListener() {
  return new Promise((resolve) => {
    const socketPath = '/work/behaviorlock-fixture.sock';
    try { fs.unlinkSync(socketPath); } catch (_) { /* absent before the fixture starts */ }
    const server = net.createServer((connection) => connection.destroy());
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      if (server.listening) {
        server.close(() => {
          try { fs.unlinkSync(socketPath); } catch (_) { /* already removed */ }
          resolve();
        });
      } else {
        resolve();
      }
    };
    server.once('error', finish);
    server.listen(socketPath, () => {
      const client = net.connect(socketPath);
      client.once('connect', () => client.destroy());
      client.once('close', finish);
      client.once('error', finish);
      client.setTimeout(500, () => {
        client.destroy();
        finish();
      });
    });
  });
}

Promise.allSettled([attemptTCP(), attemptDNSDatagram(), exerciseLoopbackListener()])
  .then(() => process.exit(0));
